  let best = -1;
  let bestGap = Infinity;
  for (let i = 0; i < remainingCapacities.length; i++) {
    const cap = remainingCapacities[i];
    if (cap >= item) {
      const gap = cap - item;
      if (gap < bestGap || (gap === bestGap && cap > remainingCapacities[best])) {
        best = i;
        bestGap = gap;
      }
    }
  }
  return best;
}","hypothesis":"Tie-break Best Fit by preferring the largest bin among ties, reducing the number of slow-grewing tight bins and improving average bin count."}

